cd /workspace && LD_LIBRARY_PATH=/workspace/native SYNECDOCHE_SITE=/workspace/site PYTHONPATH=/workspace/site python3 - <<'PY'
import json,sys,traceback
sys.path.insert(0,'submission')
from pipeline import execute
cases=json.load(open('examples.json'))
for c in cases:
    if 'raw' in c:
        continue
    try:
        ans=execute(c['request'])
        exp=c['response']
        print(c['name'])
        # print(json.dumps(ans,indent=2))
        def eq(a,b): return json.dumps(a,sort_keys=True,separators=(',',':'))==json.dumps(b,sort_keys=True,separators=(',',':'))
        print('equal',eq(ans,exp))
        if not eq(ans,exp):
            # diff sections
            for k in exp:
                if not eq(ans.get(k),exp[k]):
                    print('DIFF',k)
                    print('got',json.dumps(ans.get(k),indent=1)[:5000])
                    print('exp',json.dumps(exp[k],indent=1)[:5000])
    except Exception:
        traceback.print_exc()
PY
